CREATE   VIEW [synapse_fo].[vwDIMENSIONCOMBINATIONENTITY]
AS
SELECT T1.RECID AS RECORDID
	,T1.MAINACCOUNTVALUE AS MAINACCOUNT
	,T1.MODIFIEDDATETIME AS MODIFIEDDATETIME
	,T1.MODIFIEDBY AS MODIFIEDBY
	,T1.CREATEDDATETIME AS CREATEDDATETIME
	,T1.CREATEDBY AS CREATEDBY
	,T1.RECVERSION AS RECVERSION
	,T1.PARTITION AS PARTITION
	,T1.RECID AS RECID
	,T2.NAME AS ACCOUNTSTRUCTURE
	,T2.RECVERSION AS RECVERSION#2
	,T2.PARTITION AS PARTITION#2
	,T2.RECID AS RECID#2
	/*
	,(
		CAST((
				SELECT (
						REPLACE(REPLACE(REPLACE(CASE 
										WHEN T1.LEDGERDIMENSIONTYPE != 1
											AND SYSTEMGENERATEDATTRIBUTEBANKACCOUNT = 0
											AND SYSTEMGENERATEDATTRIBUTECUSTOMER = 0
											AND SYSTEMGENERATEDATTRIBUTEEMPLOYEE = 0
											AND SYSTEMGENERATEDATTRIBUTEEMPLOYEE_RU = 0
											AND SYSTEMGENERATEDATTRIBUTEFIXEDASSET = 0
											AND SYSTEMGENERATEDATTRIBUTEFIXEDASSETS_RU = 0
											AND SYSTEMGENERATEDATTRIBUTEITEM = 0
											AND SYSTEMGENERATEDATTRIBUTEPROJECT = 0
											AND SYSTEMGENERATEDATTRIBUTERCASH = 0
											AND SYSTEMGENERATEDATTRIBUTERDEFERRALS = 0
											AND SYSTEMGENERATEDATTRIBUTEVENDOR = 0
											THEN (
													SELECT CASE 
															WHEN NonNullDisplayValue IS NOT NULL
																THEN NonNullDisplayValue
															ELSE 'No active format for data entities has been set up.
Set up an active format for each dimension format type.'
															END
													FROM (
														SELECT (
																-- Remove initial delimiter
																STUFF((
																		SELECT
																			-- Prepend with delimiter and escape internal delimiters
																			DIMENSIONSEGMENTDELIMITER + COALESCE(REPLACE(REPLACE(DIMLIST.COLUMNVALUE, '\', '\\'), DIMENSIONSEGMENTDELIMITER, DIMENSIONSEGMENTDELIMITERESCAPED), '')
																		FROM
																			-- Get the dimension hierarchy
																			(
																			SELECT TOP (1) DH.RECID
																			FROM synapse_fo.DIMENSIONHIERARCHY DH
																			JOIN synapse_fo.DIMENSIONHIERARCHYINTEGRATION DHI ON DHI.DIMENSIONHIERARCHY = DH.RECID
																				AND DHI.ISDEFAULT = 1
																				AND DHI.PARTITION = T1.PARTITION
																			WHERE DH.PARTITION = T1.PARTITION
																				AND DH.STRUCTURETYPE = CASE T1.LEDGERDIMENSIONTYPE
																					WHEN 0
																						THEN 18
																					WHEN 2
																						THEN 19
																					WHEN 4
																						THEN 20
																					END
																			) AS DH
																		JOIN synapse_fo.DIMENSIONHIERARCHYLEVEL DHL ON DHL.DIMENSIONHIERARCHY = DH.RECID
																			AND DHL.PARTITION = T1.PARTITION
																		JOIN synapse_fo.DIMENSIONATTRIBUTE DA ON DA.RECID = DHL.DIMENSIONATTRIBUTE
																			AND DA.PARTITION = T1.PARTITION
																		LEFT JOIN (
																			SELECT DIMENSIONATTRIBUTE
																				,COLUMNVALUE
																			FROM (
																				SELECT *
																				FROM synapse_fo.DIMENSIONATTRIBUTEVALUECOMBINATION DAVC
																				WHERE DAVC.PARTITION = T1.PARTITION
																					AND DAVC.RECID = T1.RECID
																				) P
																			UNPIVOT(COLUMNVALUE FOR DIMENSIONATTRIBUTE IN (
																						CAMPAIGNYEARVALUE
																						,CHANNELVALUE
																						,COSTCENTERVALUE
																						,COUNTRYVALUE
																						,CUSTOMERVALUE
																						,ENTITYVALUE
																						,EVENTVALUE
																						,FIXEDASSETGROUPVALUE
																						,FUNCTION_VALUE
																						,INTERCOMPANYVALUE
																						,INTERIMREPORTINGENTITYVALUE
																						,LOCATIONVALUE
																						,MAINACCOUNTVALUE
																						,NEW_RENEWALVALUE
																						,PRODUCTCODEVALUE
																						,PRODUCTGROUPVALUE
																						,PROJECTVALUE
																						,SYSTEMGENERATEDATTRIBUTEBANKACCOUNTVALUE
																						,SYSTEMGENERATEDATTRIBUTECUSTOMERVALUE
																						,SYSTEMGENERATEDATTRIBUTEEMPLOYEEVALUE
																						,SYSTEMGENERATEDATTRIBUTEEMPLOYEE_RUVALUE
																						,SYSTEMGENERATEDATTRIBUTEFIXEDASSETS_RUVALUE
																						,SYSTEMGENERATEDATTRIBUTEFIXEDASSETVALUE
																						,SYSTEMGENERATEDATTRIBUTEITEMVALUE
																						,SYSTEMGENERATEDATTRIBUTEPROJECTVALUE
																						,SYSTEMGENERATEDATTRIBUTERCASHVALUE
																						,SYSTEMGENERATEDATTRIBUTERDEFERRALSVALUE
																						,SYSTEMGENERATEDATTRIBUTEVENDORVALUE
																						)) AS DIMENSIONVALUECOLUMNNAME
																			) AS DIMLIST ON DIMLIST.DIMENSIONATTRIBUTE = REPLACE(DA.DIMENSIONVALUECOLUMNNAME COLLATE Database_Default, '.', '$')
																		ORDER BY DHL.DIMENSIONHIERARCHY
																			,DHL.LEVEL_
																		FOR XML PATH('')
																		), 1, LEN(DIMENSIONSEGMENTDELIMITER), '')
																) AS NonNullDisplayValue
														) AS DisplayValueFormat
													)
										ELSE
											-- Default or dynamic accounts
											(
												SELECT REPLACE(REPLACE(T1.DISPLAYVALUE, '\', '\\'), DIMENSIONSEGMENTDELIMITER, DIMENSIONSEGMENTDELIMITERESCAPED)
												)
										END, '&amp;', '&'), '&lt;', '<'), '&gt;', '>')
						)
				FROM (
					SELECT TOP (1)
						--Determine the segment delimiter
						CASE DIMENSIONSEGMENTDELIMITER
							WHEN 0
								THEN '-'
							WHEN 1
								THEN '.'
							WHEN 2
								THEN '_'
							WHEN 3
								THEN '|'
							WHEN 7
								THEN '||'
							WHEN 8
								THEN '~'
							WHEN 4
								THEN '--'
							WHEN 5
								THEN '..'
							WHEN 6
								THEN '__'
							WHEN 9
								THEN '~~'
							END AS DIMENSIONSEGMENTDELIMITER
						,
						--Determine the account delimiter escaped
						CASE DIMENSIONSEGMENTDELIMITER
							WHEN 0
								THEN '\-'
							WHEN 1
								THEN '\.'
							WHEN 2
								THEN '\_'
							WHEN 3
								THEN '\|'
							WHEN 7
								THEN '\|\|'
							WHEN 8
								THEN '\~'
							WHEN 4
								THEN '\-\-'
							WHEN 5
								THEN '\.\.'
							WHEN 6
								THEN '\_\_'
							WHEN 9
								THEN '\~\~'
							END AS DIMENSIONSEGMENTDELIMITERESCAPED
					FROM synapse_fo.DIMENSIONPARAMETERS
					WHERE DIMENSIONPARAMETERS.PARTITION = T1.PARTITION
					) AS DIMENSIONPARAMETERS
				) AS NVARCHAR(500))
		) AS DISPLAYVALUE
*/
	,(
		CAST((
				CASE 
					WHEN (T1.SYSTEMGENERATEDATTRIBUTEBANKACCOUNTVALUE != '')
						THEN T1.SYSTEMGENERATEDATTRIBUTEBANKACCOUNTVALUE
					WHEN (T1.SYSTEMGENERATEDATTRIBUTECUSTOMERVALUE != '')
						THEN T1.SYSTEMGENERATEDATTRIBUTECUSTOMERVALUE
					WHEN (T1.SYSTEMGENERATEDATTRIBUTEEMPLOYEEVALUE != '')
						THEN T1.SYSTEMGENERATEDATTRIBUTEEMPLOYEEVALUE
					WHEN (T1.SYSTEMGENERATEDATTRIBUTEFIXEDASSETVALUE != '')
						THEN T1.SYSTEMGENERATEDATTRIBUTEFIXEDASSETVALUE
					WHEN (T1.SYSTEMGENERATEDATTRIBUTEITEMVALUE != '')
						THEN T1.SYSTEMGENERATEDATTRIBUTEITEMVALUE
					WHEN (T1.SYSTEMGENERATEDATTRIBUTEPROJECTVALUE != '')
						THEN T1.SYSTEMGENERATEDATTRIBUTEPROJECTVALUE
					WHEN (T1.SYSTEMGENERATEDATTRIBUTEVENDORVALUE != '')
						THEN T1.SYSTEMGENERATEDATTRIBUTEVENDORVALUE
					WHEN (T1.SYSTEMGENERATEDATTRIBUTEFIXEDASSETS_RUVALUE != '')
						THEN T1.SYSTEMGENERATEDATTRIBUTEFIXEDASSETS_RUVALUE
					WHEN (T1.SYSTEMGENERATEDATTRIBUTERDEFERRALSVALUE != '')
						THEN T1.SYSTEMGENERATEDATTRIBUTERDEFERRALSVALUE
					WHEN (T1.SYSTEMGENERATEDATTRIBUTERCASHVALUE != '')
						THEN T1.SYSTEMGENERATEDATTRIBUTERCASHVALUE
					WHEN (T1.SYSTEMGENERATEDATTRIBUTEEMPLOYEE_RUVALUE != '')
						THEN T1.SYSTEMGENERATEDATTRIBUTEEMPLOYEE_RUVALUE
					ELSE ''
					END
				) AS NVARCHAR(30))
		) AS ACCOUNTVALUE
	,(CAST((T1.CAMPAIGNYEARVALUE) AS NVARCHAR(30))) AS CAMPAIGNYEAR
	,(CAST((T1.CHANNELVALUE) AS NVARCHAR(30))) AS CHANNEL
	,(CAST((T1.COSTCENTERVALUE) AS NVARCHAR(30))) AS COSTCENTER
	,(CAST((T1.COUNTRYVALUE) AS NVARCHAR(30))) AS COUNTRY
	,(CAST((T1.CUSTOMERVALUE) AS NVARCHAR(30))) AS CUSTOMER
	,(CAST((T1.ENTITYVALUE) AS NVARCHAR(30))) AS ENTITY
	,(CAST((T1.FIXEDASSETGROUPVALUE) AS NVARCHAR(30))) AS FIXEDASSETGROUP
	,(CAST((T1.FUNCTION_VALUE) AS NVARCHAR(30))) AS FUNCTION_
	,(CAST((T1.INTERCOMPANYVALUE) AS NVARCHAR(30))) AS INTERCOMPANY
	,(CAST((T1.INTERIMREPORTINGENTITYVALUE) AS NVARCHAR(30))) AS INTERIMREPORTINGENTITY
	,(CAST((T1.LOCATIONVALUE) AS NVARCHAR(30))) AS LOCATION
	,(CAST((T1.NEW_RENEWALVALUE) AS NVARCHAR(30))) AS NEW_RENEWAL
	,(CAST((T1.PRODUCTCODEVALUE) AS NVARCHAR(30))) AS PRODUCTCODE
	,(CAST((T1.PRODUCTGROUPVALUE) AS NVARCHAR(30))) AS PRODUCTGROUP
	,(CAST((T1.PROJECTVALUE) AS NVARCHAR(30))) AS PROJECT
FROM synapse_fo.DIMENSIONATTRIBUTEVALUECOMBINATION T1
LEFT OUTER JOIN synapse_fo.DIMENSIONHIERARCHY T2 ON (
		(T1.ACCOUNTSTRUCTURE = T2.RECID)
		AND (T1.PARTITION = T2.PARTITION)
		)
